// wf.match.agent > "Agent input"
// Input (Start): {text (masked copy of the message), language, script, jurisdiction, today, user_id, request_id}.
// The system message is the active P6_match_agent version from the prompt registry, with its variables filled in;
// the user section (the message between <message> tags) is what the agent receives and what the memory keeps.
const s = $('Start').first().json;
const c = $('Context').first().json.c || {};
const base = { session_id: c.session_id, user_id: s.user_id, request_id: s.request_id, jurisdiction: s.jurisdiction,
  today: s.today, model: c.model, keep_alive: c.keep_alive, num_ctx: c.num_ctx, max_iterations: c.max_iterations,
  memory_turns: c.memory_turns, memory_messages: c.memory_messages, memory_text: c.memory_text || '',
  answer_max_chars: c.answer_max_chars || 400, t0: Date.now() };
if (!c.prompt) return [{ json: { ...base, ok: false, error_code: 'prompt_missing' } }];
const vars = { message: s.text, jurisdiction: s.jurisdiction || 'unknown', today: s.today, language: s.language || 'fr',
  script: s.script || 'latin' };
const fill = (t) => t.replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (m, k) => (k in vars ? String(vars[k]) : m));
const m = /##\s*system\s*\n([\s\S]*?)\n##\s*user\s*\n([\s\S]*)$/i.exec(c.prompt.template);
if (!m) return [{ json: { ...base, ok: false, error_code: 'prompt_invalid' } }];
const params = c.prompt.params || {};
return [{ json: { ...base, ok: true, system: fill(m[1].trim()), text: fill(m[2].trim()),
  prompt_version_id: c.prompt.version_id, prompt_version: c.prompt.version, num_predict: params.num_predict || 400 } }];

// wf.match.agent > "Check answer"
// The AI Agent node's answer and intermediate steps -> a checked answer and one trace step (spec 8.3).
//  - every number in the answer must come from the message, the memory or a tool result (agent_check.checkAnswer); otherwise
//    the answer is dropped and the channel shows the result cards alone (warning agent_answer_unsupported)
//  - no answer at all (model down, too many iterations) -> ok false, and the orchestrator falls back to P2 + search
// A3 Match agent checks (D-084), shared by the agent workflow and the unit tests.
//  - toolCalls(steps): the AI Agent node's intermediate steps as [{tool, input, output}] (output parsed when JSON).
//  - numbersIn(text): every reading of every number written in a text (see readings).
//  - checkAnswer(answer, sources): every number of two digits or more in the answer must appear in one of the
//    sources (the user's message, the tool results). Small numbers (result positions, counts up to 10) pass.
//  - fallbackMask(text): e-mails and long digit runs masked, used only when the Text service did not answer.
//  - plainText(answer): Markdown removed (bold, italics, headings, list markers, links), lines joined (D-085).
//  - shorten(text, max): cut at the last sentence end that fits, else at a word, with an ellipsis (D-085).

function toolCalls(steps) {
  return (Array.isArray(steps) ? steps : []).map((s) => {
    const a = s.action || {};
    let out = s.observation;
    if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { /* keep the text */ } }
    if (Array.isArray(out) && out.length === 1) out = out[0];          // a workflow tool answers with its items
    let input = a.toolInput;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { /* keep the text */ } }
    return { tool: a.tool || null, input: input ?? null, output: out ?? null };
  });
}

// Each number written in a text, with its possible readings: "450.000" is 450 (Tunisian dinars, three decimals) or
// 450000 (dot as thousands separator); "1.225.000" is 1225000; "450,5" is 450.5.
function readings(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\d{1,3}(?:\.\d{3})+(?!\d|,\d)|\d+(?:[.,]\d+)?/g)) {
    const raw = m[0];
    const alts = new Set();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(raw)) alts.add(Number(raw.replace(/\./g, '')));
    const v = Number(raw.replace(',', '.'));
    if (Number.isFinite(v)) alts.add(v);
    out.push([...alts]);
  }
  return out;
}

function numbersIn(text) {
  return readings(text).flat();
}

function checkAnswer(answer, sources) {
  const allowed = new Set();
  for (const src of sources || []) {
    const text = typeof src === 'string' ? src : JSON.stringify(src ?? '');
    for (const n of numbersIn(text)) {
      allowed.add(n);
      allowed.add(Math.round(n));
    }
  }
  const unsupported = [];
  for (const alts of readings(answer)) {
    if (alts.some((n) => Number.isInteger(n) && n <= 10)) continue;
    if (alts.some((n) => allowed.has(n) || allowed.has(Math.round(n)))) continue;
    unsupported.push(alts[alts.length - 1]);
  }
  return { ok: unsupported.length === 0, unsupported };
}

function fallbackMask(text) {
  return String(text || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '<EMAIL>')
    .replace(/\+?\d[\d .-]{6,}\d/g, (m) => (m.replace(/\D/g, '').length >= 8 ? '<PHONE>' : m));
}

function plainText(answer) {
  const lines = String(answer || '').replace(/\r/g, '').split('\n').map((l) => l
    .replace(/^\s{0,3}#{1,6}\s+/, '')                      // headings
    .replace(/^\s*(?:[-*+\u2022]|\d+[.)])\s+/, '')            // list markers ("1." too: positions are said in words)
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')                // links: keep the text
    .replace(/(\*\*|__)(.+?)\1/g, '$2')                       // bold
    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
  return lines.join(' ').replace(/\s{2,}/g, ' ').trim();
}

function shorten(text, max) {
  const t = String(text || '');
  if (!max || Array.from(t).length <= max) return { text: t, cut: false };
  const head = Array.from(t).slice(0, max).join('');
  const ends = [...head.matchAll(/[.!?\u061F\u06D4](?=\s|$)/g)].map((m) => m.index + 1);
  if (ends.length && ends[ends.length - 1] >= max * 0.4) return { text: head.slice(0, ends[ends.length - 1]).trim(), cut: true };
  const sp = head.lastIndexOf(' ');
  return { text: (sp > max * 0.4 ? head.slice(0, sp) : head).trim() + '\u2026', cut: true };
}

if (typeof module !== 'undefined') module.exports = { toolCalls, readings, numbersIn, checkAnswer, fallbackMask, plainText, shorten };

const a = $('Agent input').first().json;
const r = $input.first().json;
const calls = toolCalls(r.intermediateSteps);
const latency = Date.now() - a.t0;
const err = r.error ? String(r.error.message || r.error).slice(0, 300) : null;
// D-085: Markdown removed (Telegram shows it as raw stars), then the numbers checked, then the answer cut at the
// last sentence that fits match.agent_answer_max_chars
const raw = typeof r.output === 'string' ? r.output.trim() : '';
const markdown = /\*\*|__|^\s*(?:[-*+\u2022]|#{1,6})\s|\[[^\]]+\]\(/m.test(raw);
let answer = plainText(raw);
const warnings = [];
let dropped = null;
let cut = false;
if (answer) {
  const chk = checkAnswer(answer, [a.text, a.memory_text, ...calls.map((x) => x.output)]);
  if (!chk.ok) { dropped = { reason: 'unsupported_numbers', numbers: chk.unsupported }; warnings.push('agent_answer_unsupported'); answer = null; }
  else {
    const sh = shorten(answer, a.answer_max_chars || 400);
    if (sh.cut) { answer = sh.text; cut = true; warnings.push('agent_answer_cut'); }
  }
}
const ok = !err && (!!answer || dropped !== null);
// no raw text in the trace (D-062): tool names, sizes and counts only
const step = { agent: 'A3_match_agent', prompt_version_id: a.prompt_version_id || null, model: a.model || null,
  input: { chars: Array.from(a.text || '').length, memory_messages: a.memory_messages ?? null },
  output: { answer_chars: answer ? Array.from(answer).length : 0, raw_chars: Array.from(raw).length, markdown_removed: markdown,
            cut, dropped },
  tool_calls: calls.map((x) => ({ tool: x.tool,
    input_chars: x.input && x.input.request ? Array.from(String(x.input.request)).length : undefined,
    number: x.input && x.input.number != null ? x.input.number : undefined,
    found: x.output && typeof x.output === 'object' ? (x.output.found ?? null) : null })),
  latency_ms: latency, tokens_in: null, tokens_out: null,
  error: err || (ok ? null : 'no_answer') };
return [{ json: { ok, error_code: ok ? null : (err ? 'agent_failed' : 'no_answer'), answer: answer || null, warnings, step,
  searched: calls.some((x) => x.tool === 'search_listings'), tool_calls: calls.map((x) => x.tool),
  session_id: a.session_id, request_id: a.request_id, memory_messages: a.memory_messages } }];

// wf.match.agent > "Result": the checked answer with the cards of the search this request ran (if any).
const o = $('Check answer').first().json;
const r = ($input.first().json || {}).r || null;
const steps = [...((r && r.steps) || []), o.step];
if (!o.ok) return [{ json: { ok: false, error_code: o.error_code, steps } }];
const results = r ? r.results || [] : [];
return [{ json: { ok: true, status: r ? 'results' : 'answered', answer: o.answer, results, count: results.length,
  profile: r ? r.profile : null, anchor: r ? r.anchor : null, warnings: o.warnings, steps,
  agent: { tool_calls: o.tool_calls, memory_messages: o.memory_messages } } }];

// wf.match.agent > "No prompt": the registry has no active P6_match_agent version; the orchestrator falls back.
const a = $input.first().json;
return [{ json: { ok: false, error_code: a.error_code, steps: [{ agent: 'A3_match_agent', model: null, input: {}, output: null,
  latency_ms: 0, tokens_in: 0, tokens_out: 0, error: a.error_code }] } }];
